 para('**Når et produkt ikke virker, har kunden brug for en løsning — ikke en intern overdragelse.** EICOs Teknik & Service skal både give slutbrugere, montører og forhandlere et kvalificeret svar og sikre, at en reklamation kommer helt i mål. Som arbejdende leder med omkring 80 % operationelt arbejde skal den tekniske chef selv kunne tage de komplekse sager og samtidig skabe overblik for afdelingens tre medarbejdere.')
 para('Jeg vil begynde med at gennemgå sagsflowet sammen med teamet: hvilke oplysninger mangler ved modtagelsen, hvor opstår ventetid, hvem ejer sagen, og hvornår skal kunden eller servicepartneren have svar? EICO beder allerede om kvittering og typeskilt ved serviceanmeldelse; sammen med fejlsymptom, installation og relevante fejlkoder kan det give et bedre grundlag for at vælge næste skridt. Prioritering og svartider bør aftales med teamet og følges op i det eksisterende sagsstyringssystem.')
 para('Jeg har praktisk erfaring med de nævnte produkttyper, herunder emhætter, kogeplader, køl/frys og robotplæneklippere, samt reklamationer, garanti og international leverandørdialog. Erfaring med elinstallationer, ventilation, styring og motorer giver et grundlag for at afklare installation, kompatibilitet og fejl. EICOs produktspecifikke vejledninger, garantivilkår og beslutningsmandater skal læres, før en sag afgøres eller et indgreb udføres.')
 para('For at forbedre kvaliteten på længere sigt vil jeg sammen med produktfunktionen og leverandørerne samle tilbagevendende fejl på produkt, symptom, årsag og omkostning. Herfra kan teamet vælge konkrete tiltag, afklare reservedele og følge, om de reducerer gentagelser og garantitab. I større projekt- og bygherresager skal den tekniske løsning og de kommercielle konsekvenser afklares med salg, indkøb, lager og de relevante partnere.')
 para('Digitalisering skal fjerne dobbeltarbejde uden at fjerne ansvar: start med en fælles registreringsskabelon og tydelige næste handlinger, og vurder derefter, om automatisering eller AI kan hjælpe med kategorisering og udkast. Kvalitet, persondata og menneskelig kontrol skal være afklaret, før noget tages i brug. Hos ELOHVAC gav egne AI-værktøjer til planlægning og kvalitet et dokumenteret produktivitetsløft på over 40 %; det er ikke et resultat fra reklamationsbehandling.')
 para('EICO beskriver service som en fælles opgave for salg, service og logistik. Den sammenhæng tiltaler mig, fordi en teknisk løsning først er god, når kunden får den til at virke. Jeg leder i dag fem elektrikere og tre lærlinge med 1:1, oplæring og fuldt P&L. Jeg flytter gerne til Brønderslev-området og vil gerne drøfte, hvilke sager og processer der først har brug for opmærksomhed.')
 m.meta('Med venlig hilsen',after=5);m.meta('Shahram Ajloo · +45 93 99 95 14 · ajlooshahram@gmail.com',after=0)
 m.page_break();m.resume_header(NAME,TITLE,CONTACT,'OPGAVEN — TEKNISK SUPPORT, EJERSKAB OG OPFØLGNING')
 m.para('EICOs tekniske chef skal løse komplekse sager, lede tre medarbejdere og omsætte service- og reklamationsdata til bedre produkter og processer. Relevant erfaring: direkte teknisk service på de nævnte produkttyper samt reklamationer, garanti og international leverandørdialog; ELOHVACs otte medarbejdere og fuldt P&L; Ventek-Airs 14 medarbejdere og 11 projekter; Novo Nordisks dokumenterede kvalitets- og projektarbejde. Flytter gerne til Brønderslev-området.',after=30)
 m.section('AFKLAR, LØS, LÆR — TILGANG TIL ROLLEN')
 for a,b in [('Afklar','Registrér produkt, dokumentation, symptom og installationsforhold; aftal ejer, prioritet, næste handling og tidspunkt for tilbagemelding.'),('Løs','Fejlsøg selv eller koordinér med en servicepartner; afklar reservedele og garanti med leverandøren og kommunikér tydeligt med kunde og forhandler.'),('Lær','Følg gentagne fejl, omkostninger og svartider med produktfunktion, salg, indkøb og lager; forbedr instruktioner og arbejdsgange ud fra data.')]:m.bullet(a,b,after=10)
 m.section('ERHVERVSERFARING')
 jobs=[('Ejer / teknisk direktør / elautoriseret maskinmester','ELOHVAC ApS · København · maj 2023–nu','8 medarbejdere inkl. 3 lærlinge · fuldt P&L',[('Teknisk service og ledelse','Elinstallation, styring, ventilation og klimaanlæg: fejlfinding, forebyggende vedligehold og aflevering. Daglig planlægning, 1:1 og oplæring af fem elektrikere og tre lærlinge.'),('Kunde, økonomi og digitalisering','Tilbud, materialer og underentreprenører samt projektøkonomi; AI-værktøjer til tilbud, tidsplaner og kvalitetstjek gav over 40 % dokumenteret produktivitetsløft.')]),('Medejer og CTO / teknisk ansvarlig, AI-afdeling','Data Power Consultant ApS · København · 2024–nov. 2026 · sideløbende med ELOHVAC','4–10 personer · virksomheden ophørt',[('Digitale løsninger','Ledede tekniske og industrielle applikationer fra krav og integration til dokumentation og overdragelse; anvendte AI-assisteret udvikling med test og review.')]),('Senior commissioning engineer / projektleder, elsystemer','Novo Nordisk A/S · nov. 2022–jul. 2024','37 samtidige CAPEX-projekter · 25 specialister',[('Komplekse sager og dokumentation','Koordinerede tekniske installationer og interessenter; FAT/SAT og IQ/OQ/PQ med nul kritiske afvigelser ved aflevering. SAP ERP til økonomi, aktiver og omkostninger.')]),('Projekt- og værkstedsleder','Ventek-Air · jan. 2022–nov. 2022','14 medarbejdere · 11 samtidige projekter',[('Ventilation og koordinering','Ledede kapacitet og fremdrift i ventilationsprojekter, koordinerede underentreprenører og fulgte sikkerhed og afleveringsdokumentation.')]),('Drifts- og vedligeholdelsesleder / værkstedstekniker','BIOFOS, Lynetten · aug. 2017–jan. 2022','Kritisk 24/7-drift',[('Fejlfinding','Forebyggende vedligehold og akut fejlsøgning på elektriske og mekaniske anlæg, pumper, HVAC og styringer; 5S og PDCA.')]),('Elektromekaniker / produktionsteamleder','ARJ Engineering · dec. 2003–mar. 2010','12 mekanikere og teknikere',[('Teknik og team','Ledede vagtplanlægning og materialekoordinering; diagnosticerede og reparerede industrielt elektrisk og mekanisk udstyr.')])]
