 for a,b in [('B.Tech, Technology Management and Mechanical Engineering','Copenhagen School of Marine and Technical Engineering · 2017–2022'),('Elautoriseret maskinmester, LV/MV/HV','Sikkerhedsstyrelsen · 2023'),('PRINCE2 certificeret projektleder','AXELOS / PeopleCert'),('Køle- og ventilationsteknik','Mercantec AMU · 2021'),('El- og maskinteknisk design, elteknik','Tehran Technical University · EQF 6 · 2000–2003')]:m.edu(a,b)
 m.para('**Metoder og værktøjer:** Lean og Six Sigma anvendt i praksis, ikke certificeret; SAP ERP, Excel, Python og Claude API. **Sprog:** dansk, engelsk og persisk. **Geografi:** flytter gerne til Brønderslev-området.',after=20)
 rows=[('Arbejdende leder: 80 % drift og tre medarbejdere','ELOHVAC: dagligt teknisk arbejde og ledelse af fem elektrikere og tre lærlinge med 1:1 og oplæring. Vil tage komplekse sager og samtidig sikre opfølgning i teamet.'),('Teknisk support, diagnose og kompatibilitet','Direkte serviceerfaring på emhætter, kogeplader, køl/frys og robotplæneklippere er oplyst. ELOHVAC og Ventek-Air giver erfaring med el, styring og ventilation.'),('Service, reklamationer og garanti','Direkte ansvar for reklamationer og garantisager er bekræftet på tværs af tidligere stillinger. Vil lære EICOs konkrete vilkår og sikre sagsejer og tilbagemelding.'),('Daglig prioritering, overblik og svartider','Ventek-Air: 14 medarbejdere og 11 samtidige projekter med daglig planlægning. Vil skabe en fælles kø med prioritet, ansvar, næste handling og aftalt svartid.'),('Internationale leverandører og reservedele','Erfaring med international leverandørdialog er bekræftet. Vil afklare fejlkoder, dokumentation og reservedelsbehov med leverandør og servicepartner før næste handling.'),('Produktfejl, reklamationsstatistik og garantitab','Novo: dokumenteret afvigelses- og kvalitetsarbejde; vil analysere EICOs fejlkoder, tilbagevendende fejl og omkostninger med produktfunktion og leverandører før tiltag.'),('Kunder, forhandlere, køkkenkæder og montører','ELOHVAC: kundevendt teknisk service og afleveringer. Vil tilpasse forklaringen til slutbruger, professionel montør eller forhandler og følge sagen til en aftalt løsning.'),('Samarbejde med salg, indkøb, lager og partnere','Novo: 25 specialister på tværs af engineering, indkøb og anlæg; ELOHVAC: leverandører og underentreprenører. Vil tydeliggøre kontaktveje og sagsansvar.'),('Projekt- og bygherresager, teknik og økonomi','Novo: fremdrift, risici og økonomi på 37 projekter; ELOHVAC: tilbud og fuldt P&L. Vil afklare tekniske valg og økonomiske konsekvenser med salg og relevante parter.'),('ERP, sagsstyring og teknisk dokumentation','SAP ERP til økonomi og aktiver hos Novo samt dokumenteret aflevering. EICOs konkrete ERP- og sagsstyringssystemer er ikke specificeret og skal læres.'),('Digitalisering, automatisering og AI','ELOHVACs AI-baserede planlægning og kvalitetstjek gav over 40 % produktivitetsløft. Foreslår kontrolleret støtte til registrering og kategorisering, ikke automatisk garanti-afgørelse.'),('Medarbejderudvikling og trivsel','ELOHVAC: 1:1, oplæring og arbejdsmiljøopfølgning med otte medarbejdere. Vil aftale klare roller og udviklingsmål med EICOs tre medarbejdere.'),('Selvstændige beslutninger og servicekvalitet','Fuldt P&L i ELOHVAC og teknisk fejlfinding. Vil afveje kundehensyn, garantivilkår, sikkerhed og omkostning inden for EICOs beslutningsmandat.'),('Placering og flytning','Bosat i Måløv og indstillet på at flytte til Brønderslev-området. Tidspunkt og praktiske forhold kan aftales med EICO ved en samtale.')]
 m.models_table('OPGAVEN — ERFARING OG FØRSTE HANDLING',('Krav i rollen','Erfaring eller foreslået tilgang'),rows,widths=(2500,7846))
